package com.csi;
import com.fasterxml.jackson.databind.JsonNode;import org.springframework.stereotype.Component;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.transaction.annotation.Transactional;import java.util.*;import java.util.concurrent.TimeUnit;
@Component public class KafkaPipeline {
 final Db db;final KafkaTemplate<String,String> kafka;final Events events;final PolicyCatalog catalog;
 public KafkaPipeline(Db db,KafkaTemplate<String,String> kafka,Events events,PolicyCatalog catalog){this.db=db;this.kafka=kafka;this.events=events;this.catalog=catalog;}
 @Scheduled(fixedDelay=2000) public void outbox(){for(var row:db.list("SELECT * FROM event_outbox WHERE sent_at IS NULL AND attempts<3 AND next_attempt_at<=now() ORDER BY next_attempt_at LIMIT 10")){UUID id=UUID.fromString((String)row.get("id")),scan=UUID.fromString((String)row.get("scanId"));try{kafka.send((String)row.get("topic"),scan.toString(),db.encode(row.get("payload"))).get(8,TimeUnit.SECONDS);db.jdbc.update("UPDATE event_outbox SET sent_at=now() WHERE id=?",id);db.log(scan,"KAFKA_PUBLISHED","backend","INFO","Request delivered to Kafka");}catch(Exception e){int attempts=((Number)row.get("attempts")).intValue()+1;db.jdbc.update("UPDATE event_outbox SET attempts=?,next_attempt_at=now()+interval '5 seconds' WHERE id=?",attempts,id);db.log(scan,"KAFKA_RETRY","backend","WARN","Kafka delivery attempt "+attempts+"/3");if(attempts>=3){db.jdbc.update("UPDATE scans SET status='FAILED',finished_at=now() WHERE id=? AND status='QUEUED'",scan);db.log(scan,"DELIVERY_FAILED","backend","ERROR","Kafka delivery exhausted; manual resubmission requires a new run attempt");}}events.publish(scan.toString());}}
 @Scheduled(fixedDelay=60000) public void timeout(){for(var row:db.list("UPDATE scans SET status='FAILED',finished_at=now() WHERE status IN ('QUEUED','RUNNING') AND created_at<now()-interval '10 minutes' RETURNING id")){UUID id=UUID.fromString((String)row.get("id"));db.log(id,"SCAN_TIMEOUT","backend","ERROR","Scan exceeded execution deadline");events.publish(id.toString());}}
 @KafkaListener(topics={"scan.progress","scan.result","scan.log"}) @Transactional public void consume(String raw)throws Exception{
 JsonNode e=db.json.readTree(raw);UUID eid=UUID.fromString(e.path("eventId").asText()),scan=UUID.fromString(e.path("scanId").asText());var s=db.one("SELECT * FROM scans WHERE id=? FOR UPDATE",scan);if(!s.get("commitSha").equals(e.path("commitSha").asText())||!s.get("repository").equals(e.path("repository").asText()))throw new IllegalArgumentException("Event context mismatch");if(db.jdbc.update("INSERT INTO processed_events VALUES(?,now()) ON CONFLICT DO NOTHING",eid)==0)return;
 String type=e.path("eventType").asText();if(type.equals("SCAN_PROGRESS")){db.jdbc.update("UPDATE scans SET status='RUNNING',started_at=coalesce(started_at,now()) WHERE id=? AND status='QUEUED'",scan);db.log(scan,type,"agent","INFO","Agent analysis running");}
 else if(type.equals("SCAN_LOG")){String node=e.path("node").asText();if(!Set.of("validate_scan","load_findings","select_analysis_tools","retrieve_internal_policy","retrieve_security_guidelines","red_risk_analysis","blue_defense_verification","generate_security_report","persist_result","approval_interrupt","finalize","mcp_start","mcp_complete","llm_fallback","retry","failed").contains(node))node="agent_event";if(node.equals("finalize"))db.jdbc.update("UPDATE agent_checkpoints SET state='FINALIZED',updated_at=now() WHERE scan_id=?",scan);String tool=e.path("toolName").asText();if(!Set.of("get_scan_context","get_scan_findings","get_privacy_policy","compare_policy_with_findings","get_scan_history","request_security_review","create_security_issue","search_security_guidelines","search_internal_privacy_policy","get_guideline_details").contains(tool))tool="";db.log(scan,node,"agent",node.equals("failed")?"ERROR":"INFO",node+(tool.isEmpty()?"":" · "+tool+" · "+e.path("elapsedMs").asInt()+"ms"));}
 else if(type.equals("SCAN_RESULT")&&!Set.of("COMPLETED","FAILED").contains(s.get("status"))){String status=e.path("status").asText();if(!Set.of("COMPLETED","FAILED").contains(status))throw new IllegalArgumentException("Invalid result status");String mode=e.path("analysisMode").asText();if(!Set.of("LLM","RULE_BASED","LLM_FALLBACK","FAILED").contains(mode))throw new IllegalArgumentException("Invalid analysis mode");if(status.equals("COMPLETED")){Set<String> expected=new HashSet<>();db.list("SELECT id FROM findings WHERE scan_id=?",scan).forEach(f->expected.add((String)f.get("id")));Set<String> seen=new HashSet<>();for(JsonNode result:e.path("findings")){String fid=result.path("id").asText();if(!expected.contains(fid)||!seen.add(fid))throw new IllegalArgumentException("Invented or duplicate finding");var analysis=result.path("analysis");for(var ref:analysis.path("references")){String cid=ref.path("chunkId").asText();var original=catalog.catalog.stream().filter(c->c.get("chunkId").equals(cid)).findFirst().orElseThrow(()->new IllegalArgumentException("Invented reference"));if(!db.json.valueToTree(original).equals(ref))throw new IllegalArgumentException("Altered reference");}if(analysis.toString().length()>150000)throw new IllegalArgumentException("Oversized analysis");db.jdbc.update("UPDATE findings SET analysis=?::jsonb WHERE id=? AND scan_id=?",analysis.toString(),UUID.fromString(fid),scan);}if(!seen.equals(expected))throw new IllegalArgumentException("Incomplete result");}
 db.jdbc.update("UPDATE scans SET status=?,analysis_mode=?,finished_at=now() WHERE id=?",status,mode,scan);db.log(scan,"REPORT_SAVED","backend",status.equals("FAILED")?"ERROR":"INFO",status.equals("FAILED")?"Agent failed; analysis incomplete":"Validated report persisted");}
 events.publish(scan.toString());
 }
}
